INSERT INTO frases (emocion_id, texto) VALUES
  ((SELECT id FROM emociones WHERE clave = 'alegria'), 'Hoy la vida te sabe a algo dulce.'),
  ((SELECT id FROM emociones WHERE clave = 'alegria'), 'Tu alegría también ilumina a quienes te rodean.'),
  ((SELECT id FROM emociones WHERE clave = 'alegria'), 'Celebrar lo pequeño es otra forma de agradecer.'),
  ((SELECT id FROM emociones WHERE clave = 'alegria'), 'Que no falte una razón para sonreír hoy.'),
  ((SELECT id FROM emociones WHERE clave = 'alegria'), 'La alegría compartida sabe el doble.'),
  ((SELECT id FROM emociones WHERE clave = 'tristeza'), 'Incluso la noche más larga termina en amanecer.'),
  ((SELECT id FROM emociones WHERE clave = 'tristeza'), 'Está bien detenerse un momento a sentir.'),
  ((SELECT id FROM emociones WHERE clave = 'tristeza'), 'Lo que hoy pesa, mañana puede ser sabiduría.'),
  ((SELECT id FROM emociones WHERE clave = 'tristeza'), 'Hasta la luna descansa antes de volver a brillar.'),
  ((SELECT id FROM emociones WHERE clave = 'tristeza'), 'No tienes que explicarlo todo para que sea válido.'),
  ((SELECT id FROM emociones WHERE clave = 'ira'), 'El fuego también da calor si lo cuidas.'),
  ((SELECT id FROM emociones WHERE clave = 'ira'), 'Sentir enojo no te define; lo que haces con él, sí.'),
  ((SELECT id FROM emociones WHERE clave = 'ira'), 'Antes de responder, deja que el fuego baje.'),
  ((SELECT id FROM emociones WHERE clave = 'ira'), 'Detrás de cada enojo suele haber algo que te importa.'),
  ((SELECT id FROM emociones WHERE clave = 'ira'), 'Tu fuerza vale más cuando la usas con calma.'),
  ((SELECT id FROM emociones WHERE clave = 'miedo'), 'Hasta en la noche más oscura se aprende a ver.'),
  ((SELECT id FROM emociones WHERE clave = 'miedo'), 'Tener miedo no te hace menos valiente.'),
  ((SELECT id FROM emociones WHERE clave = 'miedo'), 'Lo desconocido también guarda cosas buenas.'),
  ((SELECT id FROM emociones WHERE clave = 'miedo'), 'Dar un paso pequeño ya es dar un paso.'),
  ((SELECT id FROM emociones WHERE clave = 'miedo'), 'Ponerle nombre al miedo le quita algo de poder.'),
  ((SELECT id FROM emociones WHERE clave = 'asco'), 'Tus límites también hablan de lo que valoras.'),
  ((SELECT id FROM emociones WHERE clave = 'asco'), 'Rechazar lo que no te gusta es una forma de cuidarte.'),
  ((SELECT id FROM emociones WHERE clave = 'asco'), 'No todo tiene que gustarte para que lo entiendas.'),
  ((SELECT id FROM emociones WHERE clave = 'asco'), 'Saber qué no quieres te acerca a lo que sí.'),
  ((SELECT id FROM emociones WHERE clave = 'asco'), 'Tomar distancia también es una decisión.'),
  ((SELECT id FROM emociones WHERE clave = 'sorpresa'), 'La vida guarda secretos que valen la pena.'),
  ((SELECT id FROM emociones WHERE clave = 'sorpresa'), 'Hoy puede pasar algo que no esperabas.'),
  ((SELECT id FROM emociones WHERE clave = 'sorpresa'), 'Lo inesperado a veces llega envuelto en dorado.'),
  ((SELECT id FROM emociones WHERE clave = 'sorpresa'), 'Quédate con la curiosidad; casi nunca falla.'),
  ((SELECT id FROM emociones WHERE clave = 'sorpresa'), 'Un instante de asombro cambia todo el día.'),
  ((SELECT id FROM emociones WHERE clave = 'desprecio'), 'Antes de juzgar, pregúntate de dónde viene el rechazo.'),
  ((SELECT id FROM emociones WHERE clave = 'desprecio'), 'Mirar con curiosidad abre más puertas que mirar por encima.'),
  ((SELECT id FROM emociones WHERE clave = 'desprecio'), 'Lo que desdeñas dice algo de lo que valoras.'),
  ((SELECT id FROM emociones WHERE clave = 'desprecio'), 'Cambiar la mirada también es cambiar la historia.'),
  ((SELECT id FROM emociones WHERE clave = 'desprecio'), 'Detrás de cada distancia hay una razón que entender.');
